// Minimal Exception Handling & Overhead

void throw_io_error() {
    // Exception object allocated by C++ Runtime (typically heap)
    throw std::ios_base::failure("Stream operation failed");
}

void integrate_error() {
    try {
        throw_io_error();
    } catch (const std::ios_base::failure& e) {
        // Runtime support (e.g., Itanium ABI) manages unwinding
        // RTTI used for type matching
        int error_code = 0xBADF00D; // Integrate internal error code
    }
}
// Note: Heap allocation often makes EH costly.
// std::terminate() called if no matching handler found.
